-- Copy public job requisitions into the isolated staging database without mutating Production.
-- Original IDs, public descriptions, departments, status, employment type, and timestamps are preserved.
-- created_by is NULL because Production's creator profile belongs to another database; do not import cross-environment user IDs.
INSERT INTO public.jobs (id, title, status, location, created_at, created_by, department, is_deleted, updated_at, description, requirements, salary_range, employment_type, responsibilities, experience_required)
SELECT id, title, status, location, created_at, created_by, department, is_deleted, updated_at, description, requirements, salary_range, employment_type, responsibilities, experience_required
FROM jsonb_populate_recordset(NULL::public.jobs, '[{"id":"5bd3ca91-81fb-47f8-9f21-57995cce6cd3","title":"Financial Risk Analyst Intern","status":"Published","location":"On-site - New Delhi","created_at":"2026-08-17T20:11:53.813573+00:00","created_by":null,"department":"Finance and Accounting","is_deleted":false,"updated_at":"2026-08-17T20:11:58.879706+00:00","description":"We are looking for motivated Financial Risk Analyst Interns to join our Risk Management team. This internship is designed for students with strong analytical and quantitative fundamentals and an interest in financial markets, risk management, and data-driven decision making. You will work alongside senior risk professionals on market risk, credit risk, financial analysis, risk modelling, and risk reporting.\n\nResponsibilities\n\n• Analyze financial data to identify potential credit, market, liquidity, and operational risks.\n• Develop and maintain financial risk models and analytical dashboards.\n• Perform quantitative analysis, stress testing, and scenario analysis.\n• Monitor key risk indicators, exposure limits, and portfolio performance.\n• Analyze financial statements, company fundamentals, and market data.\n• Assist in credit risk assessment and counterparty analysis.\n• Build automated reports and dashboards for risk monitoring and management.\n• Conduct sensitivity and what-if analysis to evaluate potential financial impacts.\n• Support senior analysts in preparing risk reports and presentations.\n• Work with large datasets to identify trends, anomalies, and emerging risks.\n• Participate in risk review meetings and contribute to risk assessment discussions.\n• Ensure risk analysis and reporting comply with internal policies and regulatory requirements.\n\nRequired Skills\n\n• Strong knowledge of Financial Risk Management, Financial Markets, and Quantitative Analysis.\n• Excellent understanding of Probability, Statistics, and basic Financial Mathematics.\n• Strong knowledge of Excel, incl