-- A narrow read-only public projection. Draft/deleted jobs and internal creator IDs are never exposed.
CREATE OR REPLACE VIEW public.published_job_cards
WITH (security_barrier = true, security_invoker = false) AS
SELECT id, title, department, location, employment_type, experience_required,
       description, requirements, responsibilities, salary_range, created_at
FROM public.jobs
WHERE status::text = 'Published'
  AND is_deleted = false;

REVOKE ALL ON public.published_job_cards FROM PUBLIC;
GRANT SELECT ON public.published_job_cards TO anon, authenticated;
